{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_summary",
        "overview_text",
        "chart_data_title",
        "chart_data_description",
        "revenue_table",
        "profit_table",
        "analysis_title",
        "analysis_text"
      ]
    },
    "title_summary": {
      "type": "Text",
      "props": {
        "text": "Quarterly Financial Performance Summary",
        "variant": "h2"
      },
      "children": []
    },
    "overview_text": {
      "type": "Text",
      "props": {
        "text": "This overview presents the financial performance across four quarters, highlighting revenue and profit trends."
      },
      "children": []
    },
    "chart_data_title": {
      "type": "Text",
      "props": {
        "text": "Revenue and Profit Trends (Data)",
        "variant": "h2"
      },
      "children": []
    },
    "chart_data_description": {
      "type": "Text",
      "props": {
        "text": "The following tables present quarterly revenue and profit trends."
      },
      "children": []
    },
    "revenue_table": {
      "type": "Table",
      "props": {
        "title": "Quarterly Revenue",
        "columns": [
          {
            "key": "Quarter",
            "label": "Quarter"
          },
          {
            "key": "Revenue",
            "label": "Revenue"
          }
        ],
        "rows": [
          {
            "Quarter": "Q1",
            "Revenue": 100000
          },
          {
            "Quarter": "Q2",
            "Revenue": 110000
          },
          {
            "Quarter": "Q3",
            "Revenue": 95000
          },
          {
            "Quarter": "Q4",
            "Revenue": 125000
          }
        ],
        "domain": "generic",
        "preferredPresentation": "table",
        "numericColumns": ["Revenue"]
      },
      "children": []
    },
    "profit_table": {
      "type": "Table",
      "props": {
        "title": "Quarterly Profit",
        "columns": [
          {
            "key": "Quarter",
            "label": "Quarter"
          },
          {
            "key": "Profit",
            "label": "Profit"
          }
        ],
        "rows": [
          {
            "Quarter": "Q1",
            "Profit": 20000
          },
          {
            "Quarter": "Q2",
            "Profit": 25000
          },
          {
            "Quarter": "Q3",
            "Profit": 18000
          },
          {
            "Quarter": "Q4",
            "Profit": 30000
          }
        ],
        "domain": "generic",
        "preferredPresentation": "table",
        "numericColumns": ["Profit"]
      },
      "children": []
    },
    "analysis_title": {
      "type": "Text",
      "props": {
        "text": "Financial Performance Analysis",
        "variant": "h2"
      },
      "children": []
    },
    "analysis_text": {
      "type": "Text",
      "props": {
        "text": "The company experienced a positive trend in both revenue and profit, culminating in its strongest performance in Q4. While Q3 saw a slight dip in both metrics, the overall trajectory indicates healthy growth and recovery towards the end of the period."
      },
      "children": []
    }
  }
}
